func rowGlyphs(s string) bool {
	for _, st := range indicator.States() {
		for _, on := range []bool{true, false} {
			if g := indicator.Glyph(st, on); g != "" && strings.Contains(s, g) {
				return true
			}
		}
	}
	return false
}

