func TestAnActionShowsTheRunningDotThatBlinks(t *testing.T) {
	on, off := indicator.Glyph(indicator.Running, true), indicator.Glyph(indicator.Running, false)
	for _, how := range []string{"stop", "restart", "pause", "remove"} {
